from __future__ import annotations
import contextlib
import io
import json
import sys
from types import ModuleType

SOURCE = '#!/usr/bin/env python3\n"""采样与谱分析参数体检。\n\n用途：任何谱分析结论落地前，先用它算清 fs / N / 窗 / 分辨率 / 混叠裕量，\n避免"频率分辨率不够却报频率""已经混叠却当真实信号"这类看似权威的错答案。\n\n只用标准库。输出 JSON（统一信封 status="ok"/"error"）。\n\n约定（口径必须先声明，脚本在输出里一并给出）：\n  df_rect      = fs/N            矩形窗 FFT 的谱线间隔\n  df_3db       = k_3db * fs/N    窗函数 -3dB 主瓣宽（两个相邻频率可分辨的经验下限）\n  nenb_bins    = 等效噪声带宽（bins），噪声功率谱需按它归一\n  cg           = 相干增益，幅值读数需除以它才是真实幅值\n  snr_db       为线性域 SNR = 信号功率 / 噪声功率（全带，实数采样）\n\n示例：\n  python signal_sanity.py --fs 10000 --n 4096 --f-max 1000 --window hann\n  python signal_sanity.py --fs 25600 --n 8192 --f-peak 1234.5 --snr-db 20 --window flattop\n"""\nimport argparse\nimport json\nimport math\nimport sys\n\n# 标称窗参数（N 足够大时收敛值；近似用于工程判断，精确值请对实际窗做数值计算）\nWINDOWS = {\n    "rect":     {"cg": 1.000, "enbw_bins": 1.000, "k_3db": 0.89,  "k_null": 2.0,  "note": "矩形窗：分辨率最好，旁瓣 -13 dB，幅值精度差"},\n    "hann":     {"cg": 0.500, "enbw_bins": 1.500, "k_3db": 1.44,  "k_null": 4.0,  "note": "汉宁窗：通用，旁瓣 -31 dB"},\n    "hamming":  {"cg": 0.540, "enbw_bins": 1.363, "k_3db": 1.30,  "k_null": 4.0,  "note": "海明窗：旁瓣 -43 dB，远端衰减慢"},\n    "blackman": {"cg": 0.420, "enbw_bins": 1.727, "k_3db": 1.68,  "k_null": 6.0,  "note": "布莱克曼窗：旁瓣 -58 dB，主瓣宽"},\n    "flattop":  {"cg": 0.2156, "enbw_bins": 3.770, "k_3db": 3.72, "k_null": 10.0, "note": "平顶窗：幅值精度最佳（<0.1%），频率分辨率差"},\n}\n\n\ndef build_parser():\n    p = argparse.ArgumentParser(description="采样与谱分析参数体检")\n    p.add_argument("--fs", type=float, required=True, help="采样率 Hz")\n    p.add_argument("--n", type=float, required=True, help="点数 N")\n    p.add_argument("--f-max", type=float, default=None, help="关心信号最高频率 Hz（用于混叠与分辨率校验）")\n    p.add_argument("--f-peak", type=float, default=None, help="实测谱峰频率 Hz（用于判断分辨率是否够）")\n    p.add_argument("--window", default="hann", choices=sorted(WINDOWS), help="窗函数")\n    p.add_argument("--snr-db", type=float, default=None, help="线性域 SNR(dB) = 信号功率/噪声功率，用于算频率估计 CRLB")\n    p.add_argument("--complex", action="store_true", help="复采样（I/Q），CRLB 方差为实信号的一半")\n    p.add_argument("--bits", type=int, default=None, help="ADC 位数，仅用于提示理论量化 SNR")\n    p.add_argument("--min-oversample", type=float, default=2.5, help="要求的 fs/f-max 最小裕量，默认 2.5")\n    return p\n\n\ndef main():\n    args = build_parser().parse_args()\n    out = {"status": "error"}\n\n    if args.fs <= 0 or args.n <= 0:\n        out["error"] = "fs 与 n 必须为正"\n        print(json.dumps(out, ensure_ascii=False, indent=2))\n        return 1\n    if args.n != int(args.n):\n        out["status"] = "error"\n        out["error"] = f"N={args.n:g} 不是整数，FFT 点数必须为整数"\n        print(json.dumps(out, ensure_ascii=False, indent=2))\n        return 1\n    if args.n < 16:\n        out["error"] = f"N={args.n:g} 太小，FFT 谱分析无意义（至少 16，工程上常需 >=256）"\n        print(json.dumps(out, ensure_ascii=False, indent=2))\n        return 1\n\n    w = WINDOWS[args.window]\n    fs = args.fs\n    n = int(args.n)\n    nyquist = fs / 2.0\n    T = n / fs\n    df_rect = fs / n\n    df_3db = w["k_3db"] * df_rect\n    df_null = w["k_null"] * df_rect\n    enbw_hz = w["enbw_bins"] * df_rect\n\n    out.update({\n        "sampling_rate_hz": fs,\n        "points": n,\n        "record_length_s": T,\n        "nyquist_hz": nyquist,\n        "window": args.window,\n        "window_note": w["note"],\n        "coherent_gain": w["cg"],\n        "enbw_bins": w["enbw_bins"],\n        "enbw_hz": enbw_hz,\n        "df_rect_hz": df_rect,\n        "df_3db_hz": df_3db,\n        "df_null_hz": df_null,\n        "conventions": {\n            "snr_db": "线性域 SNR(dB) = 信号功率 / 噪声功率（全带）",\n            "df_3db_hz": "窗函数 -3dB 主瓣宽，两个相邻频率可分辨的经验下限",\n            "coherent_gain": "幅值谱读数需除以该系数（再乘 2/N 归一）才是真实幅值",\n        },\n    })\n\n    findings = []\n    verdict = "ok"\n\n    # --- 混叠检查 ---\n    if args.f_max is not None:\n        ratio = fs / args.f_max\n        out["oversample_ratio"] = ratio\n        if args.f_max > nyquist:\n            verdict = "error"\n            findings.append({\n                "level": "error",\n                "issue": "alias",\n                "detail": f"f_max={args.f_max:g} Hz 超过奈奎斯特 {nyquist:g} Hz，信号必然混叠，结果不可用",\n                "action": "提高采样率，或在 ADC 前加模拟抗混叠滤波器把 f_max 降到 fs/2 以下",\n            })\n        elif ratio < args.min_oversample:\n            verdict = "warn" if verdict == "ok" else verdict\n            findings.append({\n                "level": "warn",\n                "issue": "low_oversample",\n                "detail": f"fs/f_max = {ratio:.2f}，低于要求的 {args.min_oversample:g} 倍",\n                "action": "确认模拟抗混叠滤波器截止频率与滚降能满足要求；否则提高 fs",\n            })\n        else:\n            findings.append({"level": "ok", "issue": "alias",\n                             "detail": f"fs/f_max = {ratio:.2f}，混叠裕量充足"})\n\n    # --- 分辨率与频率估计精度检查（f_peak 优先，否则用 f_max 作参考频率）---\n    ref = args.f_peak if args.f_peak is not None else args.f_max\n    if ref is None:\n        findings.append({\n            "level": "info", "issue": "no_reference_freq",\n            "detail": f"谱线间隔 {df_rect:.6g} Hz，{args.window} 可分辨下限约 {df_3db:.6g} Hz；"\n                      f"未给 --f-max/--f-peak，无法判定分辨率是否够",\n            "action": "补 --f-max（关心最高频率）或 --f-peak（实测谱峰）重新体检",\n        })\n    else:\n        src = "f_peak（实测谱峰）" if args.f_peak is not None else "f_max（关心最高频率）"\n        if ref > nyquist:\n            verdict = "error"\n            findings.append({\n                "level": "error", "issue": "beyond_nyquist",\n                "detail": f"参考频率 {ref:g} Hz 超过奈奎斯特 {nyquist:g} Hz（来源：{src}），该频率不可信（可能是混叠或谱轴读数错误）",\n                "action": "核对谱轴是否按 fs 归一（而非 fs/2），或提高 fs 后重测",\n            })\n        else:\n            out["reference_frequency_hz"] = ref\n            out["reference_source"] = src\n            out["reference_bin"] = ref / df_rect\n            out["reference_bin_index"] = round(ref / df_rect)\n            out["reference_offset_from_bin"] = round(ref / df_rect - round(ref / df_rect), 3)\n            out["freq_uncertainty_hz_no_interp"] = df_rect / 2.0\n            out["freq_uncertainty_note"] = "不做插值/相位法时，频率读数的不确定度至少为半个谱线间隔"\n            findings.append({\n                "level": "info", "issue": "resolution",\n                "detail": f"谱线间隔 {df_rect:.6g} Hz，{args.window} 可分辨下限约 {df_3db:.6g} Hz（参考频率来自 {src}）",\n                "action": "要分辨间隔 d 的两个频率，需 df_3db < d；直接拿 df_rect = fs/N 当分辨能力会高估",\n            })\n\n        if args.snr_db is not None:\n            snr = 10 ** (args.snr_db / 10.0)\n            factor = 6.0 if args.complex else 12.0\n            var_f = factor * fs ** 2 / ((2 * math.pi) ** 2 * snr * n * (n ** 2 - 1))\n            sd = math.sqrt(var_f)\n            out["crlb_freq_std_hz"] = sd\n            out["crlb_note"] = (\n                "单频信号在给定 SNR/点数下频率估计的标准差下界（任何算法都不会优于它）；"\n                "口径：snr = 信号功率/噪声功率（全带）" + ("，复采样" if args.complex else "，实采样")\n            )\n            if sd >= df_rect:\n                verdict = "warn" if verdict == "ok" else verdict\n                findings.append({\n                    "level": "warn", "issue": "snr_limited_frequency_estimate",\n                    "detail": f"CRLB 标准差 {sd:.4g} Hz 已不小于谱线间隔 {df_rect:.4g} Hz，"\n                              f"此 SNR 下靠插值提升频率精度无效",\n                    "action": "增加点数/记录时长，或多次相干平均（噪声降 sqrt(M)）",\n                })\n            else:\n                findings.append({\n                    "level": "ok", "issue": "crlb",\n                    "detail": f"CRLB 标准差 {sd:.4g} Hz < 谱线间隔 {df_rect:.4g} Hz，"\n                              f"插值/相位法理论上有约 {df_rect / sd:.0f} 倍提升空间（需高 SNR 才接近）",\n                })\n\n    # --- 记录时长与物理限制 ---\n    if ref is not None and ref > 0:\n        cycles = ref * T\n        out["cycles_in_record"] = cycles\n        if cycles < 10:\n            verdict = "warn" if verdict == "ok" else verdict\n            findings.append({\n                "level": "warn", "issue": "short_record",\n                "detail": f"记录长度 {T:.4g} s 仅含 {cycles:.1f} 个参考频率周期（<10）",\n                "action": "增加记录时长；注意要分辨间隔 d，记录长度至少 1/d 秒（物理限制，算法补不了）",\n            })\n\n    # --- ADC 量化提示 ---\n    if args.bits is not None:\n        if args.bits < 4 or args.bits > 32:\n            out["error"] = f"--bits={args.bits} 不合理（应在 4~32）"\n            print(json.dumps(out, ensure_ascii=False, indent=2))\n            return 1\n        snr_q = 6.02 * args.bits + 1.76\n        out["adc_ideal_snr_db"] = snr_q\n        out["adc_enob_note"] = ("理想满幅正弦量化 SNR；实际 ENOB 通常比标称少 1~3 bit，"\n                               "且需扣除信号未满幅带来的损失 20log10(满幅/实际幅度)")\n        findings.append({"level": "info", "issue": "quantization",\n                         "detail": f"{args.bits} bit 理想量化 SNR 上限约 {snr_q:.1f} dB（满幅正弦，实际更低）"})\n\n    out["verdict"] = verdict\n    out["findings"] = findings\n    out["status"] = "ok"\n    if verdict == "error":\n        out["message"] = "体检发现致命问题：当前采样/分析参数下结论不可用，先解决问题再看数据"\n    elif verdict == "warn":\n        out["message"] = "体检通过但有告警项，交付时必须一并声明"\n    else:\n        out["message"] = "采样与分析参数未见问题"\n\n    print(json.dumps(out, ensure_ascii=False, indent=2))\n    return 0 if verdict != "error" else 2\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n'

def main():
    capture, errors = io.StringIO(), io.StringIO()
    code = 0
    try:
        request = json.load(sys.stdin)
        args = request.get('args')
        if not isinstance(args, list) or any(not isinstance(x, str) for x in args):
            raise ValueError('args_must_be_string_list')
        sys.argv = ['signal_sanity.py'] + args
        module = ModuleType('__main__')
        module.__file__ = 'signal_sanity.py'
        sys.modules['__main__'] = module
        with contextlib.redirect_stdout(capture), contextlib.redirect_stderr(errors):
            exec(compile(SOURCE, 'signal_sanity.py', 'exec'), module.__dict__)
    except SystemExit as error:
        code = error.code if isinstance(error.code, int) else 1
    except Exception as error:
        code = 1
        errors.write(type(error).__name__ + ': ' + str(error))
    print(json.dumps({'exit_code': code, 'stdout': capture.getvalue(), 'stderr': errors.getvalue()}, ensure_ascii=False))
    return code

if __name__ == '__main__':
    raise SystemExit(main())
